$("btn-settings").addEventListener("click", ()=>{ renderLayoutToggles(); renderTceToggles(); updateSourcebookStatus(); populateBookSelect(); renderLoadedBookList(); $("set-addspell").checked = showAddSpell; $("set-hideportrait").checked = hidePortrait; $("set-variant-enc").checked = variantEncumbrance; $("set-futuristic").checked = showFuturistic; $("set-modern").checked = showModern; $("settings").classList.add("open"); });
$("settings-nav").addEventListener("click", e => {   // left-side section tabs
  const b = e.target.closest(".set-tab"); if(!b) return;
  document.querySelectorAll("#settings-nav .set-tab").forEach(t => t.classList.toggle("active", t === b));
  document.querySelectorAll("#settings .set-sec").forEach(s => s.classList.toggle("active", s.dataset.sec === b.dataset.sec));
});
$("set-addspell").addEventListener("change", e => { showAddSpell = e.target.checked; applyAddSpellSetting(); save(); });
$("set-hideportrait").addEventListener("change", e => { hidePortrait = e.target.checked; applyPortraitSetting(); save(); });
